// The site's Cloudflare Worker. /api requests are passed to the backend on Cloud Run with a secret
// header (the backend refuses anything without it), so every visitor, and every attack, goes through
// Cloudflare first. Everything else is the Next.js site, built by OpenNext.
// `.open-next/worker.js` is generated by `opennextjs-cloudflare build`.
import { default as site } from './.open-next/worker.js';

type Env = { API_ORIGIN: string; ORIGIN_SECRET: string };
const HOME = 'readytowork.ph';

export default {
  async fetch(request: Request, env: Env, ctx: Parameters<typeof site.fetch>[2]) {
    const url = new URL(request.url);
    // One address for everyone: www and the old names (remoteworks.ph, remotepinas.com) move permanently to readytowork.ph,
    // keeping the page path, so old links and bookmarks still work.
    if (url.hostname !== HOME && url.hostname !== 'localhost') {
      return Response.redirect(`https://${HOME}${url.pathname}${url.search}`, 301);
    }
    if (!url.pathname.startsWith('/api/')) return site.fetch(request, env, ctx);

    const headers = new Headers(request.headers);
    headers.set('x-origin-secret', env.ORIGIN_SECRET);
    headers.set('x-visitor-ip', request.headers.get('cf-connecting-ip') ?? '');
    try {
      return await fetch(new URL(url.pathname + url.search, env.API_ORIGIN), {
        method: request.method,
        headers,
        body: request.body,
        redirect: 'manual', // photo links redirect to private storage; the browser follows them itself
      });
    } catch {
      // Backend unreachable: answer like the API would, so the site shows a friendly message.
      return Response.json({ error: 'ReadyToWork.ph is having trouble right now. Please try again in a minute.' }, { status: 503 });
    }
  },
};
